#include "ksEditDecisionTask.h"
#include <algorithm>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::EditDecisionTask;using S=T::Stage;using C=T::Child;using K=T::Kind;using R=T::Route;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}struct Memory{unsigned mode,bank,row,sub,oldKnob,value;bool operator==(Memory x)const{return mode==x.mode&&bank==x.bank&&row==x.row&&sub==x.sub&&oldKnob==x.oldKnob&&value==x.value;}};
int main(){try{uint64_t cases=0;auto verify=[&](unsigned kind,unsigned mode,unsigned bank,unsigned row,unsigned sub,unsigned knob,unsigned oldKnob,unsigned delta,unsigned value,unsigned maximum,bool locked,bool available){Memory memory{mode,bank,row,sub,oldKnob,value},expected=memory;std::vector<C>children,ec;bool handoff=false;R route=R::Refresh;unsigned selection=knob,previewWrites=0;auto clamp=[&]{unsigned raw=uint8_t(bank+delta);return raw==0||raw>=128?1u:std::min(16u,raw);};auto select=[&](unsigned newBank){expected.bank=newBank;if(newBank==bank)return;if(!newBank){expected.mode=0;ec={C::RestoreScene,C::Notify};}else{if(!bank){expected.row=expected.sub=0;ec.push_back(C::Map);}if(!mode){ec.push_back(C::RestoreScene);ec.push_back(C::ActivateScene);}}handoff=true;};
if(kind==0){unsigned raw=uint8_t(oldKnob-knob),magnitude=raw>=128?uint8_t(0-raw):raw;if(magnitude>=4){expected.oldKnob=knob;if(!locked){selection=34u*knob/256;if(mode){if(!selection){expected.bank=expected.mode=0;handoff=true;}}else select(selection);}}}else if(kind==1)select(knob);else if(kind==2||kind==3){if(!mode){unsigned changed=uint8_t(row+(kind==2?1:-1));expected.row=kind==2?std::min(4u,changed):(row>0&&row<128?row-1:0);handoff=true;}else if(mode==2){handoff=true;route=kind==2?R::IncrementText:R::DecrementText;}}else if(kind==4){if(!mode){unsigned raw=uint8_t(sub+delta);expected.sub=raw>=128?3:raw>3?0:raw;ec={C::Map};handoff=true;}else if(mode==2){handoff=true;route=R::SubText;}}else if(kind==5){if(mode==2){handoff=true;route=R::AdjustText;}else if(mode){ec={C::Clamp};expected.bank=clamp();previewWrites=16;handoff=true;}else if(!row){ec={C::Clamp};selection=clamp();handoff=true;route=R::SelectBank;}else{ec={C::Field,C::ApplyScene};int adjusted=int(value)+int(int8_t(delta));expected.value=unsigned(std::max(0,std::min(adjusted,int(maximum))));handoff=true;}}else{if(!bank)expected.mode=0;else if(!mode){ec={C::Available};if(available){expected.mode=1;expected.row=0;ec.push_back(C::Backup);handoff=true;}}else if(mode==1){expected.mode=2;ec={C::Text};handoff=true;}else{ec={C::Load,C::Copy,C::RestoreParameters,C::Commit};expected.bank=expected.mode=0;handoff=true;route=R::NotifySaved;}}
T t{K(kind),uint8_t(knob),uint8_t(delta),uint8_t(knob)};unsigned previews=0,guard=0;while(!t.complete()&&!t.handoff()){check(++guard<1000,"Editdecision pure stalled");if(t.awaitingChild()){auto c=t.child();children.push_back(c);if(c==C::Clamp)check(t.resumeBank(uint8_t(clamp())),"Edit clampreply");else if(c==C::Field)check(t.resumeField(0xffffffffu,0xfffffff0u),"Edit fieldreply");else if(c==C::Available)check(t.resumeAvailable(available),"Edit availabilityreply");else check(t.resumeChild(),"Edit voidreply");continue;}auto read=[&](S s)->uint32_t{switch(s){case S::KnobReadOld:return memory.oldKnob;case S::KnobReadLock:return locked;case S::KnobReadMode:case S::SelectReadMode:case S::IncrementReadMode:case S::DecrementReadMode:case S::SubReadMode:case S::AdjustReadMode:case S::ToggleReadMode:return memory.mode;case S::SelectReadOldBank:case S::ToggleReadBank:return memory.bank;case S::IncrementReadRow:case S::DecrementReadRow:case S::AdjustReadRow:return memory.row;case S::SubReadField:return memory.sub;case S::AdjustReadValue:return memory.value;case S::AdjustReadLimit:return maximum;case S::AdjustReadPreview:return uint8_t(t.index()*17+bank);default:throw std::runtime_error("Unexpected editdecisionread");}};auto write=[&](S s,uint32_t v){switch(s){case S::KnobPublishInput:memory.oldKnob=v;break;case S::KnobPublishZeroBank:case S::SelectPublishBank:case S::AdjustPublishBank:case S::TogglePublishZeroBank:memory.bank=v;break;case S::KnobPublishZeroMode:case S::SelectPublishMode:case S::TogglePublishZeroMode:case S::TogglePublishOne:case S::TogglePublishTwo:case S::TogglePublishZero:memory.mode=v;break;case S::SelectClearRow:case S::IncrementPublishRow:case S::DecrementPublishRow:case S::TogglePublishRow:memory.row=v;break;case S::SelectClearField:case S::SubPublish:memory.sub=v;break;case S::AdjustPublishValue:check(t.field()==0xffffffffu,"Edit fielddataref");memory.value=v;break;case S::AdjustPublishPreview:check(v==uint8_t(t.index()*17+bank),"Edit previewdata");check(t.preview()==0x85ec00u+(clamp()-1)*64,"Edit previewaddress");++previews;break;default:throw std::runtime_error("Unexpected editdecisionwrite");}};auto stage=t.stage();auto cost=t.nextClocks(6);check(cost&&t.advanceBefore(cost-1,read,write,[](S){return 6u;})==0&&stage==t.stage(),"Early editdecisiondeadline");check(t.advanceBefore(cost,read,write,[](S){return 6u;})==cost,"Editdecision deadline");}
if(!(memory==expected)){std::cerr<<"kind="<<kind<<" mode="<<mode<<" bank="<<bank<<" row="<<row<<" knob="<<knob<<" delta="<<delta<<"\n";throw std::runtime_error("Independent editdecision memory oracle");}check(children==ec,"Independent editdecision child order");check(t.handoff()==handoff,"Editdecision completionkind");if(handoff)check(t.route()==route,"Editdecision route");if(route==R::SelectBank)check(t.bank()==selection,"Edit selection reply handoff");check(previews==previewWrites,"Edit previewcount");++cases;};
for(unsigned old=0;old<256;++old)for(unsigned knob=0;knob<256;++knob)for(unsigned mode:{0u,1u,2u})for(bool locked:{false,true})verify(0,mode,old,2,1,knob,old,0,0,0,locked,false);
for(unsigned bank=0;bank<256;++bank)for(unsigned knob=0;knob<256;++knob)for(unsigned mode:{0u,1u,2u})verify(1,mode,bank,2,1,knob,0,0,0,0,false,false);
for(unsigned value=0;value<256;++value)for(unsigned delta=0;delta<256;++delta)for(unsigned limit:{0u,1u,127u,255u})verify(5,0,1,1,0,0,0,delta,value,limit,false,false);
for(unsigned kind:{2u,3u,4u,5u,6u})for(unsigned raw=0;raw<256;++raw)for(unsigned delta:{0u,1u,127u,128u,255u})for(unsigned mode:{0u,1u,2u,255u})verify(kind,mode,raw,raw,raw,31,0,delta,raw,127,false,raw&1);
std::cout<<"PASS: "<<cases<<" pure knob/edit decision tasks, independent wrapped movement/clamps/field arithmetic/mode/bank/child-order oracles, typed replies and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
